INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x10v','0493x10v','x10v','0493x10v','x10 : fermeture cinétique de surface libre','Swap local full-vector one-for-one','Après relocalisation x10u, échange littéralement les vecteurs vitesse entre la particule relocalisée et un candidat local de même masse, de façon pairwise conservative en P et K.','CODE','FREE_SURFACE_KINETICS','Actif dans la chaîne liquide qualifiée; utilise un byte/particule et deux kernels conditionnels','A','2026-08-29',NULL,NULL,'Curation V4.18 fondée sur les patches historiques primaires et l’audit d’implémentation du snapshot 26/08/2026; distinguer les étapes historiques/ablations du chemin x12 qualifié.','apply_0493x10v_one_for_one_velocity_swap.py',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x10w','0493x10w','x10w','0493x10w','x10 : fermeture cinétique de surface libre','Limiter thermique local pairwise','Ajoute une redistribution locale pré-stream pour limiter le transport thermique de phase selon la résolution locale (courbure/épaisseur), avec conservation pairwise P/K; remplace un ancien limiter de position virtuelle.','CODE','FREE_SURFACE_KINETICS','Implémenté mais OFF production; exclusif avec x12a dans le snapshot audité','A','2026-08-26',NULL,NULL,'Curation V4.18 fondée sur les patches historiques primaires et l’audit d’implémentation du snapshot 26/08/2026; distinguer les étapes historiques/ablations du chemin x12 qualifié.','0493x10w_thermal_phase_limiter_review.diff',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x10x','0493x10x','x10x','0493x10x','x10 : fermeture cinétique de surface libre','Qualification de l’enveloppe thermique en C et sigma','Campagne scripts-only balayant l’épaisseur thermique via le coefficient C/sigmas et des cas de référence afin de caractériser la sensibilité de la paroi x10o sans nouvelle physique C++.','QUALIFICATION','FREE_SURFACE_KINETICS','Outil de qualification/campagne; aucun nouveau mode C++','A','2026-08-26',NULL,NULL,'Curation V4.18 fondée sur les patches historiques primaires et l’audit d’implémentation du snapshot 26/08/2026; distinguer les étapes historiques/ablations du chemin x12 qualifié.','run_0493x10x_thermal_sigmas_sweep.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x10y','0493x10y','x10y','0493x10y','x10 : fermeture cinétique de surface libre','Analyse loi taille-température de l’enveloppe','Analyse les campagnes x10x pour tester la dépendance de l’épaisseur/effet thermique avec taille, température et échelle de particule.','QUALIFICATION','FREE_SURFACE_KINETICS','Analyse scripts-only; aucun nouveau mode C++','A','2026-08-26',NULL,NULL,'Curation V4.18 fondée sur les patches historiques primaires et l’audit d’implémentation du snapshot 26/08/2026; distinguer les étapes historiques/ablations du chemin x12 qualifié.','analyze_0493x10y_size_temperature_law.py',NULL);
